  "Tu gagnes {p} % de leurs tâches": {'en': "You earn {p}% of their tasks", 'es': "Ganas {p} % de sus tareas", 'de': "Sie verdienen {p} % ihrer Aufgaben", 'ar': "تربح نسبة {p} من مهامهم", 'pt': "Você ganha {p}% das tarefas deles", 'zh': "你获得他们任务的 {p} 百分比收入", 'sw': "Unapata {p} % ya kazi zao"},
  "Les tâches s'ouvrent quelques jours après l'inscription. Reviens bientôt !": {'en': "Tasks open a few days after sign-up. Come back soon!", 'es': "Las tareas se abrirán unos días después de la inscripción. ¡Vuelve pronto!", 'de': "Die Aufgaben werden einige Tage nach der Registrierung freigeschaltet. Schauen Sie bald wieder vorbei!", 'ar': "ستُفتح المهام بعد التسجيل ببضعة أيام. ترقبوا المزيد!", 'pt': "As tarefas serão liberadas alguns dias após o cadastro. Volte em breve!", 'zh': "任务将在注册后几天内开放。请稍后再来！", 'sw': "Kazi zitafunguliwa siku chache baada ya usajili. Rudi hivi karibuni!"},
  "Choisis une tâche : tes pièces arrivent après 30 jours.": {'en': "Pick a task: your coins arrive after 30 days.", 'es': "Elige una tarea: tus monedass llegarán después de 30 días.", 'de': "Wähle eine Aufgabe: Deine Münzens kommen nach 30 Tagen an.", 'ar': "اختر مهمة: ستصلك بطاقات عملات الخاصة بك بعد 30 يومًا.", 'pt': "Escolha uma tarefa: seus moedass chegam em 30 dias.", 'zh': "选择一个任务：您的 金币 将在 30 天后到达。", 'sw': "Chagua kazi: sarafu zako zinafika baada ya siku 30."},
  "Impossible de charger les missions pour le moment. Réessaie plus tard.": {'en': "Unable to load the missions right now. Please try again later.", 'es': "Las misiones no se pueden cargar en este momento. Inténtalo de nuevo más tarde.", 'de': "Missionen können momentan nicht geladen werden. Bitte versuchen Sie es später erneut.", 'ar': "لا يمكن تحميل المهام في الوقت الحالي. يرجى المحاولة مرة أخرى لاحقاً.", 'pt': "Não foi possível carregar as missões neste momento. Tente novamente mais tarde.", 'zh': "目前无法加载任务，请稍后再试。", 'sw': "Misheni haziwezi kupakiwa kwa wakati huu. Tafadhali jaribu tena baadaye."},
  "Les missions arrivent": {'en': "Missions are coming", 'es': "Las misiones están llegando", 'de': "Die Missionen stehen bevor", 'ar': "المهمات قادمة", 'pt': "As missões estão chegando.", 'zh': "任务即将到来", 'sw': "Misheni zinakuja"},
  "Tu pourras bientôt partager des annonces et gagner des pièces.": {'en': "You will soon be able to share ads and earn coins.", 'es': "Pronto podrás compartir anuncios y ganar puntos monedas.", 'de': "Sie können demnächst Anzeigen teilen und Münzen-Punkte sammeln.", 'ar': "ستتمكن قريبًا من مشاركة الإعلانات وكسب نقاط عملات.", 'pt': "Em breve você poderá compartilhar anúncios e ganhar pontos moedas.", 'zh': "您很快就能分享广告并赚取金币积分。", 'sw': "Hivi karibuni utaweza kushiriki matangazo na kupata pointi za sarafu."},
  "{f} F par clic valide · parrainage +{p} %": {'en': "{f} F per valid click · referral +{p}%", 'es': "{f} F por clic válido · referencia +{p} %", 'de': "{f} F pro gültigem Klick · Weiterleitung +{p} %", 'ar': "{f} F لكل نقرة صالحة · إحالة +{p} %", 'pt': "{f} F por clique válido · indicação +{p} %", 'zh': "{f} F 每次有效点击 · 推荐 +{p} %", 'sw': "{f} F kwa kila mbofyo halali · rufaa +{p} %"},
  "Profil validé · {a} personnes": {'en': "Profile approved · {a} people", 'es': "Perfil verificado · Personas {a}", 'de': "Profil verifiziert · {a}-Personen", 'ar': "تم التحقق من الملف الشخصي · أشخاص {a}", 'pt': "Perfil verificado · Pessoas do {a}", 'zh': "个人资料已验证 · {a} 人", 'sw': "Wasifu umethibitishwa · Watu wa {a}"},
