  "Tâche d'un partenaire terminée": {'en': "Partner task completed", 'es': "Tarea del compañero completada", 'de': "Partneraufgabe abgeschlossen", 'ar': "تم إنجاز مهمة الشريك", 'pt': "Tarefa do parceiro concluída", 'zh': "合作伙伴任务已完成", 'sw': "Kazi ya mshirika imekamilika"},
