  "Gain de parrainage : tâche d'un filleul": {'en': "Referral earning: a friend's task", 'es': "Bonificación por recomendación: tarea de una recomendación", 'de': "Empfehlungsbonus: Aufgabe einer Empfehlung", 'ar': "مكافأة الإحالة: مهمة الإحالة", 'pt': "Bônus por indicação: tarefa de quem indica", 'zh': "推荐奖励：推荐任务", 'sw': "Bonasi ya rufaa: kazi ya rufaa"},
  "Tâche annulée par le partenaire": {'en': "Task cancelled by the partner", 'es': "Tarea cancelada por el socio", 'de': "Aufgabe vom Partner storniert", 'ar': "تم إلغاء المهمة من قبل الشريك", 'pt': "Tarefa cancelada pelo parceiro", 'zh': "任务被合作伙伴取消", 'sw': "Kazi imeghairiwa na mshirika"},
  "Partage et gagne : gains versés": {'en': "Share and earn: earnings paid", 'es': "Comparte y gana: se reparten los premios.", 'de': "Teilen und gewinnen: Gewinne werden ausgezahlt", 'ar': "شارك واربح: يتم دفع الأرباح", 'pt': "Compartilhe e ganhe: prêmios pagos", 'zh': "分享赢大奖：奖金已发放", 'sw': "Shiriki na ushinde: ushindi uliolipwa"},
  "Partage et gagne : gains retirés": {'en': "Share and earn: earnings withdrawn", 'es': "Comparte y gana: ganancias retiradas", 'de': "Teilen und gewinnen: Gewinne ausgezahlt", 'ar': "شارك واربح: سيتم سحب الأرباح", 'pt': "Compartilhe e ganhe: ganhos retirados", 'zh': "分享赢大奖：奖金已提取", 'sw': "Shiriki na ushinde: ushindi uliotolewa"},
