  "Pièces gagnées avec une publicité": {'en': "Coins earned with an ad", 'es': "Monedas ganado con un anuncio", 'de': "Münzen verdient durch eine Anzeige", 'ar': "عملات تم ربحها من خلال إعلان", 'pt': "Moedas ganhou com um anúncio", 'zh': "金币 通过广告赚取收入", 'sw': "Sarafu iliyopatikana kwa tangazo"},
  "Pièces reçues en cadeau": {'en': "Coins received as a gift", 'es': "Monedas recibido como regalo", 'de': "Münzen als Geschenk erhalten", 'ar': "عملات تم استلامه كهدية", 'pt': "Moedas recebido como presente", 'zh': "收到金币作为礼物", 'sw': "Sarafu iliyopokelewa kama zawadi"},
  "Conversion de pièces gagnées en argent": {'en': "Earned coins converted to money", 'es': "Convertir las ganancias de monedas en efectivo", 'de': "Umwandlung der verdienten Münzen in Bargeld", 'ar': "تحويل أرباح عملات إلى نقود", 'pt': "Converter moedas ganhos em dinheiro", 'zh': "将赚取的金币兑换成现金", 'sw': "Kubadilisha sarafu iliyopatikana kuwa pesa taslimu"},
  "Achat de pièces": {'en': "Coin purchase", 'es': "Compra de monedas", 'de': "Kauf von Münzen", 'ar': "شراء عملات", 'pt': "Compra de moedas", 'zh': "购买金币", 'sw': "Ununuzi wa sarafu"},
  "Dépense pièces": {'en': "Coins spent", 'es': "Gasto monedas", 'de': "Aufwand Münzen", 'ar': "المصروفات عملات", 'pt': "Despesa moedas", 'zh': "费用 金币", 'sw': "Gharama sarafu"},
