  "Remboursement": {'en': "Refund", 'es': "Reembolso", 'de': "Erstattung", 'ar': "استرداد", 'pt': "Reembolso", 'zh': "退款", 'sw': "Kurejeshewa pesa"},
  "≈ {f} F": {'en': "≈ {f} F", 'es': "≈ {f} F", 'de': "≈ {f} F", 'ar': "≈ {f} F", 'pt': "≈ {f} F", 'zh': "≈ {f} F", 'sw': "≈ {f} F"},
  "Voir toutes les consignes": {'en': "See all the instructions", 'es': "Ver todas las instrucciones", 'de': "Siehe alle Anweisungen", 'ar': "اطلع على جميع التعليمات", 'pt': "Veja todas as instruções.", 'zh': "查看所有说明", 'sw': "Tazama maagizo yote"},
  "Tu gagnes {c} pièces (≈ {f} F)": {'en': "You earn {c} coins (≈ {f} F)", 'es': "Ganas {c} monedas (≈ {f} F)", 'de': "Du gewinnst {c} Münzen (≈ {f} F)", 'ar': "لقد ربحت {c} عملات (≈ {f} F)", 'pt': "Você ganha {c} moedas (≈ {f} F)", 'zh': "你赢了 {c} 金币 (≈ {f} F)", 'sw': "Unashinda {c} sarafu (≈ {f} F)"},
  "Ce que tu dois faire": {'en': "What you have to do", 'es': "Lo que necesitas hacer", 'de': "Was Sie tun müssen", 'ar': "ما عليك فعله", 'pt': "O que você precisa fazer", 'zh': "你需要做什么", 'sw': "Unachohitaji kufanya"},
  "Détails": {'en': "Details", 'es': "Detalles", 'de': "Details", 'ar': "تفاصيل", 'pt': "Detalhes", 'zh': "细节", 'sw': "Maelezo"},
  "Commencer la tâche": {'en': "Start the task", 'es': "Iniciar la tarea", 'de': "Aufgabe starten", 'ar': "ابدأ المهمة", 'pt': "Inicie a tarefa", 'zh': "开始任务", 'sw': "Anza kazi"},
  "Le partenaire n'a pas donné de consignes : elles s'affichent sur la page de la tâche.": {'en': "The partner gave no instructions: they appear on the task page.", 'es': "El compañero no dio instrucciones: estas se muestran en la página de la tarea.", 'de': "Der Partner hat keine Anweisungen gegeben: Diese sind auf der Aufgabenseite zu finden.", 'ar': "لم يُعطِ الشريك تعليمات: بل تظهر هذه التعليمات في صفحة المهمة.", 'pt': "O parceiro não deu instruções: elas estão exibidas na página da tarefa.", 'zh': "搭档没有给出指示：指示显示在任务页面上。", 'sw': "Mshirika hakutoa maagizo: yanaonyeshwa kwenye ukurasa wa kazi."},
  "Fais la tâche toi-même, en suivant les consignes jusqu'au bout. Tes pièces sont « en attente » 30 jours, puis versées si la tâche est validée.": {'en': "Do the task yourself, following the instructions to the end. Your coins are \"pending\" for 30 days, then paid out if the task is validated.", 'es': "Completa la tarea tú mismo, siguiendo las instrucciones hasta el final. Tus puntos monedas estarán pendientes durante 30 días y se te abonarán si la tarea se valida.", 'de': "Erledigen Sie die Aufgabe selbst und folgen Sie dabei den Anweisungen bis zum Ende. Ihre Münzen-Punkte bleiben 30 Tage lang „ausstehend“ und werden erst nach erfolgreicher Bearbeitung der Aufgabe ausgezahlt.", 'ar': "أكمل المهمة بنفسك، واتبع التعليمات حتى النهاية. ستبقى نقاط عملات الخاصة بك \"معلقة\" لمدة 30 يومًا، ثم تُدفع لك إذا تم التحقق من صحة المهمة.", 'pt': "Conclua a tarefa você mesmo, seguindo as instruções até o final. Seus pontos moedas ficarão \"pendentes\" por 30 dias e serão pagos após a conclusão da tarefa, se esta for validada.", 'zh': "请自行完成任务，并严格按照说明完成。您的金币积分将“待处理”30天，任务审核通过后才会发放。", 'sw': "Kamilisha kazi mwenyewe, ukifuata maagizo hadi mwisho. Pointi zako za sarafu \"zinasubiri\" kwa siku 30, kisha utalipwa ikiwa kazi imethibitishwa."},
  "Achat en direct (argent protégé jusqu'à la réception)": {'en': "Live purchase (your money is protected until delivery)", 'es': "Compra directa (dinero protegido hasta su recepción)", 'de': "Direktkauf (Geld ist bis zum Erhalt geschützt)", 'ar': "شراء مباشر (الأموال محمية حتى الاستلام)", 'pt': "Compra direta (dinheiro protegido até o recebimento)", 'zh': "直接购买（资金安全保障，直至收到货款）", 'sw': "Ununuzi wa moja kwa moja (pesa inalindwa hadi itakapopokelewa)"},
  "Achat en direct : {t} (argent protégé jusqu'à la réception)": {'en': "Live purchase: {t} (your money is protected until delivery)", 'es': "Compra directa: {t} (dinero protegido hasta su recepción)", 'de': "Direktkauf: {t} (Geld geschützt bis zum Erhalt)", 'ar': "الشراء المباشر: {t} (الأموال محمية حتى الاستلام)", 'pt': "Compra direta: {t} (dinheiro protegido até o recebimento)", 'zh': "直接购买：{t}（资金安全保障，直至收到货）", 'sw': "Ununuzi wa moja kwa moja: {t} (pesa inalindwa hadi itakapopokelewa)"},
  "Vente en direct : fonds reçus après confirmation de réception": {'en': "Live sale: funds received after delivery was confirmed", 'es': "Venta directa: fondos recibidos tras la confirmación de la recepción.", 'de': "Direktverkauf: Zahlungseingang nach Empfangsbestätigung", 'ar': "البيع المباشر: يتم استلام الأموال بعد تأكيد الاستلام", 'pt': "Venda direta: fundos recebidos após a confirmação do recebimento.", 'zh': "直接销售：确认收款后收到的款项", 'sw': "Mauzo ya moja kwa moja: pesa zilizopokelewa baada ya uthibitisho wa risiti"},
  "Commande annulée : remboursement": {'en': "Order cancelled: refund", 'es': "Pedido cancelado: reembolso", 'de': "Bestellung storniert: Rückerstattung", 'ar': "تم إلغاء الطلب: استرداد المبلغ", 'pt': "Pedido cancelado: reembolso", 'zh': "订单已取消：退款", 'sw': "Agizo limefutwa: marejesho ya pesa"},
  "Commande annulée : remboursement moins la pénalité d'annulation": {'en': "Order cancelled: refund minus the cancellation penalty", 'es': "Pedido cancelado: reembolso menos gastos de cancelación.", 'de': "Bestellung storniert: Rückerstattung abzüglich Stornogebühr", 'ar': "تم إلغاء الطلب: المبلغ المسترد مطروحًا منه رسوم الإلغاء", 'pt': "Pedido cancelado: reembolso menos taxa de cancelamento.", 'zh': "订单已取消：退款金额将扣除取消费用", 'sw': "Agizo limefutwa: marejesho ya pesa bila ada ya kughairi"},
  "Choisis une mission ou une tâche.": {'en': "Pick a mission or a task.", 'es': "Elige una misión o tarea.", 'de': "Wähle eine Mission oder Aufgabe.", 'ar': "اختر مهمة أو تكليفًا.", 'pt': "Escolha uma missão ou tarefa.", 'zh': "选择一项任务或任务。", 'sw': "Chagua dhamira au kazi."},
  "Fais-la en suivant les consignes.": {'en': "Do it following the instructions.", 'es': "Hazlo siguiendo las instrucciones.", 'de': "Führen Sie die Schritte gemäß den Anweisungen aus.", 'ar': "قم بذلك باتباع التعليمات.", 'pt': "Faça isso seguindo as instruções.", 'zh': "请按照说明操作。", 'sw': "Fanya hivyo kwa kufuata maelekezo."},
  "Tes pièces arrivent « en attente », puis sont versées : tu les convertis en argent.": {'en': "Your coins arrive as \"pending\", then are paid out: you convert them to money.", 'es': "Tus monedas llegan \"pendientes\" y luego se te pagan: los conviertes en dinero.", 'de': "Ihre Münzen werden zunächst als \"ausstehend\" angezeigt und anschließend ausgezahlt: Sie tauschen sie in Geld um.", 'ar': "تصل عملات عملات الخاصة بك \"معلقة\"، ثم يتم دفعها: تقوم بتحويلها إلى نقود.", 'pt': "Seus moedas chegam \"pendentes\" e depois são pagos: você os converte em dinheiro.", 'zh': "您的 金币 到达时会显示“待处理”状态，然后会被支付：您可以将其兑换成现金。", 'sw': "Sarafu yako inafika \"imesubiriwa\", kisha hulipwa: unaibadilisha kuwa pesa."},
  "Lire plus": {'en': "Read more", 'es': "Leer más", 'de': "Mehr lesen", 'ar': "اقرأ المزيد", 'pt': "Leia mais", 'zh': "阅读更多", 'sw': "Soma zaidi"},
  "Les missions (Partage et gagne)": {'en': "Missions (Share and earn)", 'es': "Las misiones (Comparte y gana)", 'de': "Die Missionen (Teilen und gewinnen)", 'ar': "المهام (شارك واربح)", 'pt': "As missões (Compartilhe e ganhe)", 'zh': "任务（分享赢大奖）", 'sw': "Misheni (Shiriki na ushinde)"},
  "Tu partages des annonces sur WhatsApp, Telegram, Facebook ou TikTok avec ton lien personnel. Chaque clic valide te rapporte des pièces. Elles restent « en attente » {h} h, puis elles sont ajoutées à ton solde.": {'en': "You share ads on WhatsApp, Telegram, Facebook or TikTok with your personal link. Every valid click earns you coins. They stay \"pending\" for {h} h, then are added to your balance.", 'es': "Comparte anuncios en WhatsApp, Telegram, Facebook o TikTok usando tu enlace personal. Cada clic válido te genera monedas. Estos permanecen \"pendientes\" durante {h} horas y luego se suman a tu saldo.", 'de': "Du teilst Anzeigen auf WhatsApp, Telegram, Facebook oder TikTok über deinen persönlichen Link. Jeder erfolgreiche Klick bringt dir Münzen ein. Die Anzeigen bleiben {h} Stunden lang „ausstehend“ und werden dann deinem Guthaben gutgeschrieben.", 'pt': "Você compartilha anúncios no WhatsApp, Telegram, Facebook ou TikTok usando seu link pessoal. Cada clique válido te rende moedas. Eles ficam \"pendentes\" por {h} horas e depois são adicionados ao seu saldo.", 'zh': "您可以使用个人链接在 WhatsApp、Telegram、Facebook 或 TikTok 上分享广告。每次有效点击可赚取 金币。这些奖励会保留 {h} 小时，之后会添加到您的余额中。", 'sw': "Unashiriki matangazo kwenye WhatsApp, Telegram, Facebook, au TikTok kwa kutumia kiungo chako cha kibinafsi. Kila mbofyo halali unapata sarafu. Yanabaki \"yakisubiri\" kwa saa za {h}, kisha yanaongezwa kwenye salio lako."},
  "Les tâches de nos partenaires": {'en': "Our partners' tasks", 'es': "Las tareas de nuestros socios", 'de': "Die Aufgaben unserer Partner", 'ar': "مهام شركائنا", 'pt': "As tarefas dos nossos parceiros", 'zh': "我们合作伙伴的任务", 'sw': "Kazi za washirika wetu"},
  "Jeux, sondages et applications : tu choisis une tâche, tu la fais en suivant ses consignes (traduites dans ta langue quand c'est possible). Tes pièces sont « en attente » {n} jours : nos partenaires vérifient ton travail et peuvent annuler une tâche en cas de fraude.": {'en': "Games, surveys and apps: you pick a task and do it following its instructions (translated into your language when possible). Your coins are \"pending\" for {n} days: our partners check your work and can cancel a task in case of fraud.", 'es': "Juegos, encuestas y aplicaciones: elige una tarea y complétala siguiendo las instrucciones (traducidas a tu idioma cuando sea posible). Tus monedass estarán pendientes durante {n} días: nuestros socios revisarán tu trabajo y podrían cancelar una tarea en caso de fraude.", 'de': "Spiele, Umfragen und Apps: Sie wählen eine Aufgabe und erledigen sie anhand der Anweisungen (wenn möglich in Ihre Sprache übersetzt). Ihre Münzens sind für {n} Tage „ausstehend“: Unsere Partner prüfen Ihre Arbeit und können eine Aufgabe im Betrugsfall stornieren.", 'pt': "Jogos, pesquisas e aplicativos: você escolhe uma tarefa e a conclui seguindo as instruções (traduzidas para o seu idioma, quando possível). Seus moedass ficam \"pendentes\" por {n} dias: nossos parceiros verificam seu trabalho e podem cancelar uma tarefa em caso de fraude.", 'zh': "游戏、调查和应用：您选择一项任务，并按照说明完成（尽可能翻译成您的语言）。您的 金币 任务将“待处理” {n} 天：我们的合作伙伴会审核您的任务，如有欺诈行为，可能会取消任务。", 'sw': "Michezo, tafiti, na programu: unachagua kazi na kuikamilisha kwa kufuata maagizo (yaliyotafsiriwa katika lugha yako inapowezekana). sarafu zako \"zinasubiri\" kwa siku za {n}: washirika wetu huangalia kazi yako na wanaweza kughairi kazi iwapo kutatokea ulaghai."},
  "Convertir en argent": {'en': "Convert to money", 'es': "Convertir a efectivo", 'de': "In Bargeld umwandeln", 'ar': "تحويل إلى نقد", 'pt': "Converter em dinheiro", 'zh': "兑换成现金", 'sw': "Badilisha kuwa pesa taslimu"},
  "Quand tes pièces sont versées, elles rejoignent tes pièces gagnées. Tu peux les convertir en argent réel : 25 pièces valent 10 F.": {'en': "Once your coins are paid out, they join your earned coins. You can convert them to real money: 25 coins are worth 10 F.", 'es': "Cuando se te paguen tus monedas, se añadirán a tus monedas ganados. Puedes convertirlos en dinero real: 25 monedas equivalen a 10 F.", 'de': "Sobald Ihre Münzen ausgezahlt sind, werden sie Ihren verdienten Münzen hinzugefügt. Sie können diese in echtes Geld umtauschen: 25 Münzen entsprechen 10 F.", 'ar': "عند استلام أرباحك من عملات، تُضاف إلى رصيدك من عملات. يمكنك تحويلها إلى نقود حقيقية: 25 عملات تساوي 10 F.", 'pt': "Quando seus moedas forem pagos, eles serão adicionados aos seus moedas ganhos. Você pode convertê-los em dinheiro real: 25 moedas valem 10 F.", 'zh': "当您的 金币 获得支付时，它们将添加到您已获得的 金币 中。您可以将它们兑换成真钱：25 个 金币 价值 10 福林。", 'sw': "Sarafu yako inapolipwa, huongezwa kwenye sarafu yako uliyopata. Unaweza kuzibadilisha kuwa pesa halisi: sarafu 25 zina thamani ya 10 F."},
  "Invite tes amis": {'en': "Invite your friends", 'es': "Invita a tus amigos", 'de': "Lade deine Freunde ein", 'ar': "ادعُ أصدقاءك", 'pt': "Convide seus amigos", 'zh': "邀请你的朋友", 'sw': "Alika marafiki zako"},
  "Tu gagnes en plus un pourcentage de ce que gagnent tes amis, sans rien leur retirer.": {'en': "You also earn a percentage of what your friends earn, without taking anything from them.", 'es': "Además, tú ganas un porcentaje de lo que ganan tus amigos, sin quitarles nada.", 'de': "Sie erhalten außerdem einen Prozentsatz von dem, was Ihre Freunde verdienen, ohne dass ihnen etwas weggenommen wird.", 'ar': "كما أنك تربح نسبة مئوية مما يربحه أصدقاؤك، دون أن تأخذ أي شيء منهم.", 'pt': "Você também ganha uma porcentagem do que seus amigos ganham, sem tirar nada deles.", 'zh': "你还可以从朋友的收入中获得一定比例的收益，而不会减少他们的任何收入。", 'sw': "Pia unapata asilimia ya kile ambacho marafiki zako wanapata, bila kuwanyang'anya chochote."},
  "À respecter": {'en': "Rules", 'es': "Ser respetado", 'de': "Respekt verdienen", 'ar': "أن تحظى بالاحترام", 'pt': "Para ser respeitado", 'zh': "受人尊敬", 'sw': "Kuheshimiwa"},
  "Fais chaque tâche toi-même et une seule fois. Une tâche non conforme peut être refusée, et un gain peut être retiré en cas de fraude.": {'en': "Do each task yourself and only once. A non-compliant task can be refused, and earnings can be withdrawn in case of fraud.", 'es': "Completa cada tarea tú mismo y solo una vez. Si no cumples con los requisitos, podrías ser rechazado y, en caso de fraude, podrías retirar las ganancias.", 'de': "Erledigen Sie jede Aufgabe selbst und nur einmal. Eine nicht ordnungsgemäß erledigte Aufgabe kann abgelehnt werden, und im Falle von Betrug können Gewinne einbehalten werden.", 'ar': "أكمل كل مهمة بنفسك ومرة ​​واحدة فقط. قد يتم رفض المهمة غير المتوافقة مع الشروط، وقد يتم سحب الأرباح في حالة الاحتيال.", 'pt': "Complete cada tarefa individualmente e apenas uma vez. Tarefas não cumpridas poderão ser rejeitadas e os ganhos poderão ser retirados em caso de fraude.", 'zh': "每项任务必须由本人独立完成，且只能完成一次。不符合规定的任务可能会被拒绝，如有欺诈行为，奖金可能会被取消。", 'sw': "Kamilisha kila kazi mwenyewe na mara moja tu. Kazi isiyofuata sheria inaweza kukataliwa, na ushindi unaweza kutolewa iwapo kutatokea udanganyifu."},
  "vous a passé une commande": {'en': "placed an order with you", 'es': "Usted realizó un pedido", 'de': "Sie haben eine Bestellung aufgegeben", 'ar': "لقد قمت بتقديم طلب", 'pt': "Você fez um pedido", 'zh': "您已下单", 'sw': "Uliweka agizo"},
  "a validé la commande": {'en': "accepted the order", 'es': "Se validó el pedido", 'de': "Bestellung bestätigt", 'ar': "تم التحقق من صحة الطلب", 'pt': "validou o pedido", 'zh': "订单已验证", 'sw': "imethibitisha agizo hilo"},
  "a modifié les frais de livraison : acceptez-les ou refusez": {'en': "changed the delivery fee: accept or refuse it", 'es': "Ha cambiado los gastos de envío: acéptelos o rechácelos.", 'de': "Die Lieferkosten haben sich geändert: Akzeptieren oder ablehnen", 'ar': "تم تغيير رسوم التوصيل: اقبلها أو ارفضها", 'pt': "As taxas de entrega foram alteradas: aceite ou recuse-as?", 'zh': "运费已更改：接受或拒绝", 'sw': "imebadilisha gharama za usafirishaji: zikubali au zikatae"},
  "a expédié votre commande": {'en': "shipped your order", 'es': "ha enviado su pedido", 'de': "Ihre Bestellung wurde versandt", 'ar': "تم شحن طلبك", 'pt': "Seu pedido foi enviado.", 'zh': "您的订单已发货", 'sw': "imetuma oda yako"},
  "a confirmé la réception : l'argent est versé": {'en': "confirmed delivery: the money is paid out", 'es': "Recibo confirmado: el dinero ha sido pagado.", 'de': "Empfangsbestätigung: Das Geld wurde bezahlt.", 'ar': "تم تأكيد الاستلام: تم دفع المبلغ", 'pt': "Comprovante de pagamento: o dinheiro foi pago.", 'zh': "已确认收到款项：款项已支付", 'sw': "Risiti iliyothibitishwa: pesa imelipwa"},
  "a annulé la commande": {'en': "cancelled the order", 'es': "canceló el pedido", 'de': "Bestellung storniert", 'ar': "تم إلغاء الطلب", 'pt': "pedido cancelado", 'zh': "取消订单", 'sw': "kughairi agizo"},
  "a signalé un problème sur la commande": {'en': "reported a problem with the order", 'es': "reportó un problema con el pedido", 'de': "Es wurde ein Problem mit der Bestellung gemeldet.", 'ar': "أبلغ عن وجود مشكلة في الطلب", 'pt': "Relatou um problema com o pedido.", 'zh': "报告订单存在问题。", 'sw': "iliripoti tatizo na agizo"},
  "L'équipe a tranché le litige de la commande": {'en': "Our team settled the order dispute", 'es': "El equipo resolvió la disputa del pedido.", 'de': "Das Team hat den Bestellstreit beigelegt.", 'ar': "قام الفريق بحل النزاع المتعلق بالطلب", 'pt': "A equipe resolveu a disputa sobre o pedido.", 'zh': "团队解决了订单纠纷。", 'sw': "Timu ilitatua mgogoro wa agizo"},
  "propose un prix sur votre article": {'en': "offered a price on your item", 'es': "Ofrezca un precio por su artículo.", 'de': "Machen Sie einen Preis für Ihren Artikel", 'ar': "حدد سعرًا لمنتجك", 'pt': "Ofereça um preço ao seu produto.", 'zh': "请为您的商品报价", 'sw': "toa bei ya bidhaa yako"},
  "a répondu à votre offre": {'en': "replied to your offer", 'es': "respondí a tu oferta", 'de': "hat auf Ihr Angebot geantwortet", 'ar': "لقد استجبت لعرضك", 'pt': "respondeu à sua oferta", 'zh': "已回复您的报价", 'sw': "alijibu ofa yako"},
  "Commandes": {'en': "Orders", 'es': "Órdenes", 'de': "Bestellungen", 'ar': "طلبات", 'pt': "Pedidos", 'zh': "订单", 'sw': "Maagizo"},
  "Vente en direct : administration": {'en': "Live selling: administration", 'es': "Ventas directas: administración", 'de': "Direktvertrieb: Verwaltung", 'ar': "المبيعات المباشرة: الإدارة", 'pt': "Vendas diretas: administração", 'zh': "直销：管理", 'sw': "Mauzo ya moja kwa moja: utawala"},
  "Vente en direct : équipe": {'en': "Live selling: team", 'es': "Ventas directas: equipo", 'de': "Direktvertrieb: Team", 'ar': "المبيعات المباشرة: فريق", 'pt': "Vendas diretas: equipe", 'zh': "直销团队", 'sw': "Mauzo ya moja kwa moja: timu"},
  "Litiges": {'en': "Disputes", 'es': "Disputas", 'de': "Streitigkeiten", 'ar': "النزاعات", 'pt': "Disputas", 'zh': "争议", 'sw': "Migogoro"},
  "En séquestre": {'en': "Held in escrow", 'es': "Bajo secuestro", 'de': "Im Rahmen der Sequestrierung", 'ar': "في ظل الحجز", 'pt': "Sob sequestro", 'zh': "在预算削减期间", 'sw': "Chini ya kunyang'anywa"},
  "Commissions": {'en': "Commissions", 'es': "Comisiones", 'de': "Provisionen", 'ar': "العمولات", 'pt': "Comissões", 'zh': "佣金", 'sw': "Tume"},
  "Ventes terminées": {'en': "Completed sales", 'es': "Las ventas terminaron", 'de': "Verkäufe beendeten", 'ar': "انتهت المبيعات", 'pt': "As vendas terminaram", 'zh': "销售结束", 'sw': "Mauzo yamekwisha"},
  "Commandes terminées": {'en': "Completed orders", 'es': "Pedidos completados", 'de': "Abgeschlossene Bestellungen", 'ar': "تم إتمام الطلبات", 'pt': "Pedidos concluídos", 'zh': "订单已完成", 'sw': "Maagizo yamekamilika"},
  "Aucun litige à trancher.": {'en': "No dispute to settle.", 'es': "No hay disputa que resolver.", 'de': "Kein Streitfall zu klären.", 'ar': "لا يوجد نزاع يستدعي الحل.", 'pt': "Nenhuma disputa a ser resolvida.", 'zh': "无需解决争议。", 'sw': "Hakuna mzozo wa kusuluhisha."},
  "Aucune commande.": {'en': "No orders.", 'es': "No hay pedidos.", 'de': "Keine Bestellungen.", 'ar': "لا توجد طلبات.", 'pt': "Sem pedidos.", 'zh': "没有订单。", 'sw': "Hakuna maagizo."},
  "Article, acheteur ou vendeur": {'en': "Item, buyer or seller", 'es': "Artículo, comprador o vendedor", 'de': "Artikel, Käufer oder Verkäufer", 'ar': "السلعة، المشتري أو البائع", 'pt': "Item, comprador ou vendedor", 'zh': "物品、买家或卖家", 'sw': "Bidhaa, mnunuzi au muuzaji"},
  "Toutes": {'en': "All", 'es': "Todo", 'de': "Alle", 'ar': "الجميع", 'pt': "Todos", 'zh': "全部", 'sw': "Zote"},
  "Rembourser l'acheteur": {'en': "Refund the buyer", 'es': "Reembolsar al comprador", 'de': "Dem Käufer eine Rückerstattung gewähren", 'ar': "رد المبلغ للمشتري", 'pt': "Reembolsar o comprador", 'zh': "退款给买家", 'sw': "Rudisha pesa kwa mnunuzi"},
  "Payer le vendeur": {'en': "Pay the seller", 'es': "Paga al vendedor", 'de': "Bezahle den Verkäufer", 'ar': "ادفع للبائع", 'pt': "Pague ao vendedor", 'zh': "向卖家付款", 'sw': "Mlipe muuzaji"},
  "Décision enregistrée.": {'en': "Decision saved.", 'es': "Decisión registrada.", 'de': "Entscheidung protokolliert.", 'ar': "تم تسجيل القرار.", 'pt': "Decisão registrada.", 'zh': "决定已记录。", 'sw': "Uamuzi umerekodiwa."},
  "Rembourser l'acheteur ({f}) sans pénalité ? Le vendeur ne reçoit rien.": {'en': "Refund the buyer ({f}) with no penalty? The seller receives nothing.", 'es': "¿Se le devuelve el dinero al comprador ({f}) sin penalización? El vendedor no recibe nada.", 'de': "Dem Käufer ({f}) ohne Strafgebühr eine Rückerstattung gewähren? Der Verkäufer erhält nichts.", 'ar': "هل يُرد المبلغ للمشتري ({f}) دون غرامة؟ البائع لا يحصل على شيء.", 'pt': "Reembolsar o comprador ({f}) sem penalidade? O vendedor não recebe nada.", 'zh': "退款给买家（{f}）不收取任何费用？卖家一分钱也拿不到。", 'sw': "Utarudisha pesa kwa mnunuzi ({f}) bila adhabu? Muuzaji hatapata chochote."},
  "Verser l'argent au vendeur ? L'acheteur ne sera pas remboursé.": {'en': "Pay the seller? The buyer will not be refunded.", 'es': "¿Pagarle al vendedor? El comprador no recibirá ningún reembolso.", 'de': "Den Verkäufer bezahlen? Der Käufer erhält keine Rückerstattung.", 'ar': "هل تدفع للبائع؟ لن يتم تعويض المشتري.", 'pt': "Pagar ao vendedor? O comprador não será reembolsado.", 'zh': "付钱给卖家？买家将无法获得补偿。", 'sw': "Mlipe muuzaji? Mnunuzi hatalipwa."},
  "{p} · acheteur {b} · vendeur {s}": {'en': "{p} · buyer {b} · seller {s}", 'es': "{p} · Comprador {b} · Vendedor {s}", 'de': "{p} · Käufer {b} · Verkäufer {s}", 'ar': "{p} · المشتري {b} · البائع {s}", 'pt': "{p} · Comprador {b} · Vendedor {s}", 'zh': "{p} · 买家 {b} · 卖家 {s}", 'sw': "{p} · Mnunuzi {b} · Muuzaji {s}"},
  "Ton argent est protégé : le vendeur n'est payé que lorsque tu confirmes la réception. Un problème ? Tu es remboursé.": {'en': "Your money is protected: the seller is only paid once you confirm delivery. A problem? You get refunded.", 'es': "Tu dinero está protegido: el vendedor solo recibe el pago una vez que confirmas la recepción. ¿Algún problema? Te reembolsaremos el dinero.", 'de': "Ihr Geld ist geschützt: Der Verkäufer erhält sein Geld erst nach Ihrer Empfangsbestätigung. Bei Problemen erhalten Sie Ihr Geld zurück.", 'ar': "أموالك محمية: لا يتم الدفع للبائع إلا بعد تأكيد استلامك للمنتج. هل لديك أي مشكلة؟ ستسترد أموالك.", 'pt': "Seu dinheiro está protegido: o vendedor só recebe o pagamento após você confirmar o recebimento. Algum problema? Você receberá um reembolso.", 'zh': "您的资金安全有保障：只有在您确认收货后，卖家才会收到款项。如有任何问题，您将获得退款。", 'sw': "Pesa zako zinalindwa: muuzaji hulipwa tu mara tu unapothibitisha kupokea. Kuna matatizo yoyote? Utarejeshewa pesa."},
  "Ton code de livraison": {'en': "Your delivery code", 'es': "Tu código de entrega", 'de': "Ihr Liefercode", 'ar': "رمز التوصيل الخاص بك", 'pt': "Seu código de entrega", 'zh': "您的配送代码", 'sw': "Nambari yako ya uwasilishaji"},
  "Donne-le au vendeur ou au livreur SEULEMENT quand tu as ta commande en main : il déclenche le paiement du vendeur.": {'en': "Give it to the seller or courier ONLY once you hold your order: it triggers the seller's payment.", 'es': "Entrégaselo al vendedor o al repartidor ÚNICAMENTE cuando tengas tu pedido en mano: así se activa el pago al vendedor.", 'de': "Geben Sie es dem Verkäufer oder Lieferanten erst dann, wenn Sie Ihre Bestellung in Händen halten: Dadurch wird die Zahlung des Verkäufers ausgelöst.", 'ar': "قم بتسليمها للبائع أو مندوب التوصيل فقط عندما يكون طلبك في يدك: فهذا يؤدي إلى دفع البائع.", 'pt': "Entregue o comprovante de pagamento ao vendedor ou entregador SOMENTE quando tiver o pedido em mãos: isso aciona o pagamento do vendedor.", 'zh': "只有当您收到订单后才能将其交给卖家或送货员：这样才能触发卖家的付款。", 'sw': "Mpe muuzaji au mtu anayeleta bidhaa PEKEE unapokuwa na oda yako mkononi: itasababisha malipo ya muuzaji."},
  "Saisir le code de livraison": {'en': "Enter the delivery code", 'es': "Introduzca el código de entrega", 'de': "Geben Sie den Liefercode ein.", 'ar': "أدخل رمز التوصيل", 'pt': "Digite o código de entrega", 'zh': "请输入配送代码", 'sw': "Ingiza msimbo wa uwasilishaji"},
  "Code à 4 chiffres donné par l'acheteur à la remise": {'en': "4-digit code given by the buyer at hand-over", 'es': "Código de 4 dígitos proporcionado por el comprador en el momento de la entrega.", 'de': "4-stelliger Code, den der Käufer bei der Lieferung angibt", 'ar': "رمز مكون من 4 أرقام يقدمه المشتري وقت التسليم", 'pt': "Código de 4 dígitos fornecido pelo comprador no momento da entrega.", 'zh': "买家在交货时提供的4位数代码", 'sw': "Nambari ya tarakimu 4 iliyotolewa na mnunuzi wakati wa uwasilishaji"},
  "Livraison confirmée : ton argent est versé.": {'en': "Delivery confirmed: your money is paid out.", 'es': "Entrega confirmada: su pago ha sido realizado.", 'de': "Lieferung bestätigt: Ihr Geld wurde bezahlt.", 'ar': "تم تأكيد التسليم: تم دفع المبلغ المستحق.", 'pt': "Entrega confirmada: seu pagamento foi efetuado.", 'zh': "已确认发货：您的款项已支付。", 'sw': "Uwasilishaji umethibitishwa: pesa zako zimelipwa."},
  "Noter le vendeur": {'en': "Rate the seller", 'es': "Califica al vendedor", 'de': "Bewerten Sie den Verkäufer", 'ar': "قيّم البائع", 'pt': "Avalie o vendedor", 'zh': "给卖家评分", 'sw': "Kadiria muuzaji"},
  "Comment s'est passé cet achat ?": {'en': "How did this purchase go?", 'es': "¿Cómo fue esta compra?", 'de': "Wie verlief der Kauf?", 'ar': "كيف سارت عملية الشراء هذه؟", 'pt': "Como foi essa compra?", 'zh': "这次购物体验如何？", 'sw': "Ununuzi huu uliendaje?"},
  "Un mot sur le vendeur (facultatif)": {'en': "A word about the seller (optional)", 'es': "Unas palabras sobre el vendedor (opcional)", 'de': "Ein Wort zum Verkäufer (optional)", 'ar': "كلمة عن البائع (اختياري)", 'pt': "Uma palavra sobre o vendedor (opcional)", 'zh': "关于卖家的一句话（可选）", 'sw': "Neno moja kuhusu muuzaji (hiari)"},
  "Plus tard": {'en': "Later", 'es': "Más tarde", 'de': "Später", 'ar': "لاحقاً", 'pt': "Mais tarde", 'zh': "之后", 'sw': "Baadaye"},
  "Envoyer mon avis": {'en': "Send my review", 'es': "Enviar mi reseña", 'de': "Meine Bewertung einreichen", 'ar': "أرسل تقييمي", 'pt': "Enviar minha avaliação", 'zh': "提交我的评论", 'sw': "Wasilisha ukaguzi wangu"},
  "Merci pour ton avis !": {'en': "Thanks for your review!", 'es': "¡Gracias por tus comentarios!", 'de': "Vielen Dank für Ihr Feedback!", 'ar': "شكراً لتعليقاتكم!", 'pt': "Obrigado pelo seu feedback!", 'zh': "感谢您的反馈！", 'sw': "Asante kwa maoni yako!"},
  "Code promo {c} : -{f}": {'en': "Promo code {c}: -{f}", 'es': "Código promocional {c}: -{f}", 'de': "Gutscheincode {c}: -{f}", 'ar': "رمز الخصم {c}: -{f}", 'pt': "Código promocional {c}: -{f}", 'zh': "优惠码 {c}：-{f}", 'sw': "Msimbo wa ofa {c}: -{f}"},
  "{n} produits · fais défiler": {'en': "{n} products · swipe", 'es': "Productos {n} · desplazarse", 'de': "{n}-Produkte · scrollen", 'ar': "منتجات {n} · تصفح", 'pt': "Produtos {n} · rolagem", 'zh': "{n}产品 · 滚动", 'sw': "Bidhaa za {n} · tembeza"},
  "Durée maximale atteinte ({m} min) : fin du live.": {'en': "Maximum duration reached ({m} min): the live is ending.", 'es': "Duración máxima alcanzada ({m} min): fin de la transmisión en vivo.", 'de': "Maximale Dauer erreicht ({m} min): Ende des Livestreams.", 'ar': "تم الوصول إلى أقصى مدة ({m} دقيقة): نهاية البث المباشر.", 'pt': "Duração máxima atingida ({m} min): fim da transmissão ao vivo.", 'zh': "直播时长已达上限（{m} 分钟）：直播结束。", 'sw': "Muda wa juu zaidi umefikiwa (dakika ya {m}): mwisho wa mtiririko wa moja kwa moja."},
  "Ton live se termine dans 2 minutes (durée maximale : {m} min).": {'en': "Your live ends in 2 minutes (maximum duration: {m} min).", 'es': "Tu transmisión en vivo terminará en 2 minutos (duración máxima: {m} min).", 'de': "Ihr Livestream endet in 2 Minuten (maximale Dauer: {m} min).", 'pt': "Sua transmissão ao vivo terminará em 2 minutos (duração máxima: {m} min).", 'zh': "您的直播将在 2 分钟后结束（最长持续时间：{m} 分钟）。", 'sw': "Mtiririko wako wa moja kwa moja utaisha ndani ya dakika 2 (muda wa juu zaidi: dakika ya {m})."},
  "Ton live arrive à sa fin": {'en': "Your live is about to end", 'es': "Tu transmisión en directo está llegando a su fin.", 'de': "Ihr Livestream neigt sich dem Ende zu.", 'ar': "سينتهي بثك المباشر قريباً.", 'pt': "Sua transmissão ao vivo está chegando ao fim.", 'zh': "您的直播即将结束。", 'sw': "Mtiririko wako wa moja kwa moja unakaribia kuisha."},
  "Il se termine dans 2 minutes. Continue encore {m} min pour {p}.": {'en': "It ends in 2 minutes. Keep going for {m} more min for {p}.", 'es': "Termina en 2 minutos. Continúa durante {m} min durante {p}.", 'de': "Es endet in 2 Minuten. Weiter für {m} min für {p}.", 'ar': "ينتهي خلال دقيقتين. استمر لمدة دقيقة واحدة ({m}) لمدة دقيقة واحدة ({p}).", 'pt': "Termina em 2 minutos. Continue por {m} min para {p}.", 'zh': "还有2分钟结束。继续进行{m}分钟，直到{p}结束。", 'sw': "Inaisha baada ya dakika 2. Endelea kwa dakika ya {m} kwa {p}."},
  "Terminer à l'heure": {'en': "End on time", 'es': "Terminar a tiempo", 'de': "Pünktlich fertig werden", 'ar': "الانتهاء في الوقت المحدد", 'pt': "Terminar no prazo", 'zh': "按时完成", 'sw': "Maliza kwa wakati"},
  "Prolonger": {'en': "Extend", 'es': "Extender", 'de': "Verlängern", 'ar': "يمتد", 'pt': "Estender", 'zh': "延长", 'sw': "Panua"},
